function appendChatPair(user,model,userIndex,modelIndex){var th=$('#talk-thread');if(!th||screen!=='workspace'||workspaceView!=='talk')return false;var quick=th.querySelector('.quick-start-shell');if(quick)quick.remove();th.insertAdjacentHTML('beforeend',renderChatMessage(user,userIndex)+renderChatMessage(model,modelIndex));var ap=$('.attach-preview');if(ap)ap.remove();requestAnimationFrame(function(){th.scrollTop=th.scrollHeight;updateJump()});return true}
