async function ask(text){text=String(text||'').trim();if(busy)return;if(!activePlate())return toast('Carga un vehículo primero.');if(!text&&!pendingImage)return;if(!text)text='Analiza esta foto en el contexto de este vehículo.';var key=chatKey(),list=db.chats[key]=db.chats[key]||[],img=pendingImage;pendingImage='';var user={role:'user',text:text+(img?' [foto adjunta]':''),at:Date.now()},model={role:'model',text:'',at:Date.now()+1,streaming:true};list.push(user,model);var userIndex=list.length-2,modelIndex=list.length-1;busy=true;markActivity();persist(['chats','vehicles']);if(!appendChatPair(user,model,userIndex,modelIndex)){render();scrollChatEnd()}try{var before=list.slice(0,-1);await geminiStream({systemInstruction:{parts:[{text:L.buildSystemPrompt(cur)}]},contents:buildContents(before,img),generationConfig:{temperature:.25}},function(chunk){model.text+=chunk;updateStreamingModel(modelIndex,model)});model.streaming=false;if(!model.text.trim())throw new Error('La IA no devolvió una respuesta.')}catch(e){model.streaming=false;model.error=true;model.text=e.message||'No pude responder.'}busy=false;if(list.length>60)db.chats[key]=list.slice(-60);persist(['chats']);patchChatMessage(modelIndex,model)}
