function renderChatMessage(m,i){if(m.role==='user')return'<div class="user-pill" data-chat-index="'+i+'"><div>'+esc(m.text)+'</div><div class="msg-time">'+fmtTime(m.at)+'</div></div>';var certainty=parseCertainty(m.text);return'<article class="ai-doc'+(m.error?' error':'')+(m.streaming?' streaming':'')+'" data-chat-index="'+i+'"><div class="ai-head"><span class="ai-label">THOKAR IA</span>'+(!m.error?'<span class="certainty '+certainty+'">Certeza '+certainty+'</span>':'')+'</div><div class="ai-content" data-ai-content="'+i+'">'+renderAiBody(m,i)+'</div><div class="ai-actions">'+(m.error?'<button class="ai-action" data-retry="'+i+'">'+I.search+' Reintentar</button>':'<button class="ai-action" data-copy-msg="'+i+'">'+I.copy+' Copiar</button><button class="ai-action" data-save-msg="'+i+'">'+I.save+' Registrar diagnóstico</button><button class="ai-action" data-check-msg="'+i+'">'+I.check+' Crear checklist</button><button class="ai-action" data-share-msg="'+i+'">'+I.share+' Compartir</button>')+'</div><div class="msg-time">'+fmtTime(m.at)+'</div></article>'}
