function zonePrompt(z){
  var cfg={motor:{title:'¿Qué problema tiene el motor?',prompts:['El motor falla en ralentí','El motor perdió potencia','Se encendió el check engine','Hay ruido o golpeteo en el motor']},frenos:{title:'¿Qué problema tienen los frenos?',prompts:['Suena al frenar','El pedal está esponjoso','Se va hacia un lado al frenar','Vibra al frenar']},suspension:{title:'¿Qué problema tiene la suspensión?',prompts:['Suena al pasar baches','Hay juego o vibración','Se siente inestable','El auto quedó desnivelado']},direccion:{title:'¿Qué problema tiene la dirección?',prompts:['El volante quedó duro','Tira hacia un lado','Hay juego en dirección','Suena al girar']},electrico:{title:'¿Qué problema tiene el sistema eléctrico?',prompts:['No parte o cuesta partir','La batería se descarga','No está cargando bien','Hay luces débiles o fallas eléctricas']},transmision:{title:'¿Qué problema tiene la transmisión?',prompts:['Entran mal los cambios','Hay patinaje o tirones','Hace ruido la caja','Pierde aceite de transmisión']},refrigeracion:{title:'¿Qué problema tiene la refrigeración?',prompts:['Se calienta el motor','No prende el electroventilador','Hay fuga de refrigerante','La calefacción no calienta']},combustible:{title:'¿Qué problema tiene el sistema de combustible?',prompts:['Le cuesta encender','Pierde fuerza en aceleración','Sospecha de bomba o filtro','Huele a combustible o hay fuga']}};
  var c=cfg[z]||{title:'¿Qué problema tiene esta zona?',prompts:['Quiero revisar esta zona del vehículo']};
  openModal('<h2 class="sheet-title">'+esc(c.title)+'</h2><p class="muted" style="margin-top:-8px">Elige una opción o escribe una pregunta propia para <strong>'+esc(cur.plate)+'</strong>.</p><div class="action-grid zone-prompt-grid">'+c.prompts.map(function(p){return'<button class="action-tile zone-prompt-tile" data-zone-text="'+esc(p)+'">'+I.chat+'<span>'+esc(p)+'</span></button>'}).join('')+'</div><div class="custom-zone-query"><label for="zone-custom-question">Otra pregunta</label><textarea id="zone-custom-question" rows="3" placeholder="Ej. ¿Cómo verifico si el sensor de cigüeñal está fallando?"></textarea><button class="btn primary block" id="zone-custom-send">Enviar pregunta personalizada</button></div>',function(sheet){function sendPrompt(prompt){if(!prompt)return toast('Escribe tu pregunta.');closeModal();setTimeout(function(){if(workspaceView!=='talk')mountWorkspaceView('talk',{scroll:true});else{scrollWorkspaceToContent();fitTalkWindow()}ask(prompt);setTimeout(scrollChatEnd,80)},210)}$$('[data-zone-text]',sheet).forEach(function(b){b.addEventListener('click',function(){sendPrompt('Necesito ayuda con esta zona del vehículo: '+b.getAttribute('data-zone-text')+'. Hazme preguntas y dame pasos para diagnosticarlo.')})});$('#zone-custom-send',sheet).addEventListener('click',function(){var q=$('#zone-custom-question',sheet).value.trim();sendPrompt(q)})},{full:true})
}
